function sweptHit(ball, prevX, prevY, brick) {
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const L = brick.x - ball.r;
  const R = brick.x + brick.w + ball.r;
  const T = brick.y - ball.r;
  const B = brick.y + brick.h + ball.r;

  let tmin = 0, tmax = 1;
  let tX = -1, tY = -1; // entry times per axis
  let hit = true;

  if (Math.abs(dx) < 1e-9) {
    if (prevX < L || prevX > R) hit = false;
  } else {
    let t1 = (L - prevX)/dx;
    let t2 = (R - prevX)/dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tX = t1;
    tmin = Math.max(tmin, t1);
    tmax = Math.min(tmax, t2);
  }
  if (!hit) return null;
  if (Math.abs(dy) < 1e-9) {
    if (prevY < T || prevY > B) hit = false;
  } else {
    let t1 = (T - prevY)/dy;
    let t2 = (B - prevY)/dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tY = t1;
    tmin = Math.max(tmin, t1);
    tmax = Math.min(tmax, t2);
  }
  if (!hit) return null;
  if (tmin > tmax || tmin < 0 || tmin > 1) return null;

  // determine face(s)
  const CORNER_EPS = 1e-6;
  if (tX >= 0 && tY >= 0 && Math.abs(tX - tY) < CORNER_EPS) {
    return { axis: 'corner', t: tmin };
  }
  if (tX >= 0 && (tY < 0 || tX > tY)) return { axis:'x', t: tmin };
  if (tY >= 0) return { axis:'y', t: tmin };
  return { axis: tX >= 0 ? 'x':'y', t: tmin };
}
