// Swept AABB: does the ball's path (from the previous frame to the current one)
// cross this brick? Returns the axis of the face entered ('x', 'y' or 'corner'),
// or null if the path never touches the brick. The brick rect is inflated by the
// ball radius, and the ball is treated as a moving point.
function sweptHitFace(px, py, dx, dy, r, brick) {
  const L = brick.x - r;
  const R = brick.x + brick.w + r;
  const T = brick.y - r;
  const B = brick.y + brick.h + r;

  let tmin = 0;
  let tmax = 1;
  let tX = -Infinity;
  let tY = -Infinity;
  let valid = true;

  if (Math.abs(dx) < 1e-9) {
    if (px < L || px > R) valid = false;
  } else {
    let t1 = (L - px) / dx;
    let t2 = (R - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tX = t1;
    tmin = Math.max(tmin, t1);
    tmax = Math.min(tmax, t2);
  }

  if (Math.abs(dy) < 1e-9) {
    if (py < T || py > B) valid = false;
  } else {
    let t1 = (T - py) / dy;
    let t2 = (B - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tY = t1;
    tmin = Math.max(tmin, t1);
    tmax = Math.min(tmax, t2);
  }

  if (!valid || tmin > tmax || tmin < 0 || tmin > 1) return null;

  // Corner: the two faces are crossed at (almost) the same time.
  if (tX !== -Infinity && tY !== -Infinity && Math.abs(tX - tY) < 1e-6) {
    return 'corner';
  }
  // Otherwise the face entered last is the one we hit.
  return tY === -Infinity || (tX !== -Infinity && tX > tY) ? 'x' : 'y';
}
```

